pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockDelta, uint256 depositAmount, uint256 collectAmount) public {
        // Bound values to reasonable ranges
        unlockDelta = bound(unlockDelta, 0, 1000000);
        depositAmount = bound(depositAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, 100 ether);

        // Setup: fund caller and put with unlock time
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(block.timestamp + unlockDelta);

        // Advance time past unlock
        vm.warp(block.timestamp + unlockDelta + 1);

        // Get balances before collect
        uint256 callerBalanceBefore = address(caller).balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call Collect - may revert
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get balances after
        uint256 callerBalanceAfter = address(caller).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: the sum of caller balance and contract balance cannot increase by more than msg.value
        // (here msg.value sent is 0 for Collect, so sum should be <= before)
        bool rule = (callerBalanceAfter + contractBalanceAfter) <= (callerBalanceBefore + contractBalanceBefore);
        assertTrue(rule);
    }
}

