pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 initialBalance, uint256 unlockTime, uint256 amount) public {
        vm.assume(user != address(0) && user != address(this));
        amount = bound(amount, 1, 100 ether);
        // Ensure initialBalance is exactly MinSum so reference allows Collect but mutant does not
        // We set MinSum to 1 ether by default, so we must set initialBalance to exactly 1 ether
        vm.assume(initialBalance >= 1 ether);
        // We want the condition that acc.balance >= MinSum holds exactly at border
        // Actually we want to test when acc.balance == MinSum; we set initialBalance = 1 ether
        // To make it simple, we bound and fix initialBalance = 1 ether exactly
        vm.assume(initialBalance == 1 ether);
        // Ensure time condition passes
        vm.warp(unlockTime + 1);
        // Deploy contract and fund the user with exact balance
        vm.deal(user, initialBalance);
        // User puts money to set balance = initialBalance and unlockTime
        vm.prank(user);
        c.Put{value: initialBalance}(unlockTime);
        // Now collect with amount less than or equal to balance (>= amount condition uses _am)
        amount = bound(amount, 0, initialBalance);
        uint256 balBefore = address(user).balance;
        // Attempt Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));
        // In reference: allowed because balance >= MinSum (equal), so Collect should succeed
        // In mutant: not allowed because balance > MinSum is false
        // The rule: IF Collect reverted, then the user's balance does not change
        if (!success) {
            assertTrue(balBefore == address(user).balance, "Revert should keep balance unchanged");
        }
        // If succeed, balance decreases by amount (checked by other tests)
    }
}

