pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 balanceBefore, uint256 unlockTime) public {
        // Ensure caller is not the zero address
        vm.assume(caller != address(0));
        // Bound unlockTime to avoid overflow
        unlockTime = bound(unlockTime, 0, type(uint256).max - 1);
        // Set the caller's balance in the contract to exactly MinSum
        uint256 minSum = c.MinSum();
        // We need to fund the caller and have them deposit exactly MinSum
        vm.deal(caller, minSum);
        vm.prank(caller);
        c.Put{value: minSum}(unlockTime);
        // Now the caller has exactly MinSum balance in the contract
        // Advance time so unlockTime is in the past
        vm.warp(unlockTime + 1);
        // Try to collect MinSum (the balance is exactly MinSum)
        vm.prank(caller);
        // For reference C, condition acc.balance >= MinSum is true, so Collect proceeds
        // For mutant M, condition acc.balance > MinSum is false, so Collect does nothing
        // Record balance before call
        uint256 balanceBeforeCall = c.Acc(caller).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, minSum));
        assertTrue(success);
        uint256 balanceAfterCall = c.Acc(caller).balance;
        // The property: if balanceBeforeCall equals MinSum, then after Collect with amount=MinSum,
        // the balance should be unchanged in the mutant (since condition fails) and become 0 in reference.
        // But we assert the reference behavior: balance decreases by the collected amount.
        // Since we know the reference allows Collect when balance == MinSum, the balance becomes 0.
        // To write a general rule that passes on reference and fails on mutant:
        // For the reference, when balance == MinSum and amount == MinSum, Collect succeeds and balance becomes 0.
        // For the mutant, when balance == MinSum and amount == MinSum, Collect does nothing and balance stays MinSum.
        // So the rule: the balance after Collect is either 0 (reference) or MinSum (mutant).
        // But we need a single assertion. We can assert: the balance after Collect is not equal to balanceBeforeCall.
        // That holds for reference (0 != MinSum) but fails for mutant (MinSum == MinSum).
        assertTrue(balanceAfterCall != balanceBeforeCall, "Balance should change when collecting exactly MinSum");
    }
}

