pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockTimeOffset, uint256 deposit, uint256 collectAmt) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.assume(deposit >= 1 ether);
        vm.assume(collectAmt <= deposit);
        vm.assume(unlockTimeOffset > block.timestamp);

        // First, fund the caller exactly to MinSum (1 ether) by putting deposit (>= 1 ether) then sending extra back
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put{value: deposit}(unlockTimeOffset);

        // Use a second account to drain excess above MinSum so caller's balance is exactly MinSum
        address temp = address(0xDEAD);
        vm.deal(temp, 1 ether);
        vm.prank(temp);
        c.Put{value: 1 ether}(unlockTimeOffset);
        // Now temp has 1 ether balance. Have temp call Collect for 1 ether to drain it so we can disburse
        // Actually simpler: directly adjust: we just need the caller's balance to be exactly MinSum = 1 ether.
        // If deposit > 1 ether, we can send back the excess to caller via a collect? No, better to just restrict assume.
        vm.assume(deposit == 1 ether); // force caller exactly at MinSum

        // Fast-forward to after unlockTime
        vm.warp(unlockTimeOffset + 1);

        // Now call Collect with caller; since balance == MinSum (not >) the reference should succeed, mutant may revert
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // General rule: when caller's balance == MinSum and collectAmt <= MinSum, Collect should succeed
        assertTrue(success, "Collect should succeed when caller balance == MinSum");
    }
}

