pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant MIN_SUM = 1 ether;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(putAmount >= 0.001 ether && putAmount <= 100 ether);
        vm.assume(collectAmount >= 0.001 ether && collectAmount <= putAmount);
        vm.assume(unlockTime >= 0 && unlockTime <= 30 days);

        // Ensure caller has enough ETH to put
        vm.deal(caller, putAmount);

        // Set block timestamp to a known value
        vm.warp(0);

        // Caller puts ETH with a lock time
        vm.prank(caller);
        c.Put{value: putAmount}(block.timestamp + unlockTime);

        // Fast forward to after unlockTime
        vm.warp(block.timestamp + unlockTime + 1);

        // Record balance before Collect
        uint balanceBefore = c.Acc(caller).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: if Collect succeeds, the caller's balance decreases exactly by collectAmount
        // If Collect fails (reverts or returns false), balance unchanged (but we check the true path)
        if (success && balanceBefore >= MIN_SUM && balanceBefore >= collectAmount) {
            uint balanceAfter = c.Acc(caller).balance;
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collectAmount");
        } else {
            // For this test, we only check non-reverting cases; reverted cases are skipped
            // But we still need one assertion; we assert a trivial truth to avoid compile error
            assertTrue(true);
        }
    }
}

